    /* ================= CHI TIẾT SÂU — SERVICE CỐT LÕI ================= */
    var CORE = [
    {c:'aws',n:'Amazon EC2',g:'Compute',gl:'server',lvl:0,d:'Máy chủ ảo thuê theo giờ/giây, toàn quyền chọn CPU, RAM, OS, network. Là nền tảng compute gốc của AWS — mọi kiến trúc truyền thống đều bắt đầu từ đây.',u:['Web/app server cần kiểm soát OS hoàn toàn','Phần mềm legacy, license gắn máy (BYOL)','Batch/HPC với instance chuyên dụng (GPU, network cao)'],lim:'AZ là biên chịu lỗi: instance chết theo AZ trừ khi có ASG multi-AZ. EBS volume cũng gắn AZ.',pr:'Trả theo giây: On-Demand / Reserved / Savings Plans (giảm tới ~72%) / Spot (giảm tới ~90%, bị thu hồi).',cfg:'aws ec2 run-instances \\\n  --image-id ami-0abcdef1234567890 \\\n  --instance-type t3.micro \\\n  --key-name my-key --security-group-ids sg-0123 \\\n  --subnet-id subnet-0abc --count 1',vs:'EC2 vs Lambda: EC2 khi tiến trình chạy dài/điều khiển OS; Lambda khi sự kiện ngắn < 15 phút.',err:'Mở SSH 0.0.0.0/0, dùng instance đơn lẻ không ASG, quên gắn IAM Role mà nhúng access key vào máy.'},
    {c:'aws',n:'AWS Lambda',g:'Compute',gl:'lambda',lvl:0,d:'Chạy code theo sự kiện, không quản lý server, tự scale từ 0 đến hàng nghìn request đồng thời. Timeout tối đa 15 phút, RAM 128MB–10GB.',u:['API backend qua API Gateway','Xử lý file khi có object mới trên S3','Cron job, ETL nhẹ, webhook'],lim:'Cold start với VPC/runtime nặng; giới hạn concurrency theo region (mặc định 1000, tăng được).',pr:'Tính theo số request + GB-giây. 1 triệu request đầu mỗi tháng miễn phí.',cfg:'# Tạo function từ zip\ndocker: zip function.zip lambda_function.py\naws lambda create-function --function-name hello \\\n  --runtime python3.12 --handler lambda_function.handler \\\n  --role arn:aws:iam::123456789012:role/lambda-role \\\n  --zip-file fileb://function.zip',vs:'Lambda vs Fargate: Lambda cho việc ngắn theo sự kiện; Fargate cho container chạy dài, kiểm soát môi trường hơn.',err:'Để timeout 3 giây mặc định cho tác vụ dài, không đặt reserved concurrency cho hàm quan trọng, log không cấu trúc khó debug.'},
    {c:'aws',n:'Amazon S3',g:'Storage',gl:'bucket',lvl:0,d:'Lưu trữ object gần như không giới hạn, độ bền 99.999999999% (11 số 9). Nền của data lake, backup, static web, và là điểm hội tụ của hầu hết pipeline dữ liệu.',u:['Data lake (raw/curated), backup & archive','Hosting web tĩnh, phân phối qua CloudFront','Nguồn dữ liệu cho Athena/Glue/EMR'],lim:'Object tối đa 5TB (multipart trên 100MB). S3 không phải filesystem — latency cao hơn EBS/EFS.',pr:'Theo GB-tháng theo storage class (Standard → Intelligent-Tiering → Glacier) + phí request + phí truyền dữ liệu ra.',cfg:'aws s3api create-bucket --bucket my-data-lake \\\n  --region ap-northeast-1 \\\n  --create-bucket-configuration LocationConstraint=ap-northeast-1\naws s3api put-bucket-versioning --bucket my-data-lake \\\n  --versioning-configuration Status=Enabled\naws s3 sync ./data s3://my-data-lake/raw/',vs:'S3 vs EBS vs EFS: S3 = object qua API; EBS = block cho 1 instance; EFS = filesystem chia sẻ nhiều instance.',err:'Bucket public do quên Block Public Access, không bật versioning/MFA Delete cho dữ liệu quan trọng, để dữ liệu nóng mãi ở Standard.'},
    {c:'aws',n:'Amazon RDS',g:'Database',gl:'db',lvl:0,d:'Database quan hệ managed (MySQL, PostgreSQL, MariaDB, Oracle, SQL Server): AWS lo backup, patch, failover Multi-AZ, read replica.',u:['DB cho ứng dụng web/ERP truyền thống','Nâng cấp từ DB tự cài trên EC2 (replatform)','Read replica để giảm tải đọc'],lim:'Failover Multi-AZ mất ~30–120 giây đổi DNS. Scale dọc còn giới hạn theo instance class.',pr:'Theo giờ instance + GB storage + IOPS; Multi-AZ tính đôi. Database Savings Plans (2025) giảm chi phí khi cam kết dùng.',cfg:'aws rds create-db-instance \\\n  --db-instance-identifier prod-db \\\n  --db-instance-class db.t3.medium --engine postgres \\\n  --master-username admin --allocated-storage 100 \\\n  --multi-az --storage-encrypted',vs:'RDS vs Aurora: Aurora đắt hơn ~20% nhưng scale storage tự động, replica nhanh, hiệu năng cao hơn cho workload lớn.',err:'Đặt RDS ở public subnet / mở port 5432 ra internet, không bật automated backup đúng RPO, storage không bật autoscaling.'},
    {c:'aws',n:'Amazon DynamoDB',g:'Database',gl:'table',lvl:1,d:'NoSQL key-value/document serverless, latency mili-giây một chữ số ở mọi quy mô, tự scale không giới hạn thực tế.',u:['Session, giỏ hàng, hồ sơ người dùng','Dữ liệu IoT/game cần ghi cực nhanh','Backend serverless cùng Lambda/API Gateway'],lim:'Item tối đa 400KB. Query hiệu quả phụ thuộc thiết kế partition key — thiết kế sai là “hot partition”.',pr:'On-demand (theo request) hoặc provisioned (RCU/WCU); Global Table tính thêm phí replication.',cfg:'aws dynamodb create-table --table-name Orders \\\n  --attribute-definitions AttributeName=orderId,AttributeType=S \\\n  --key-schema AttributeName=orderId,KeyType=HASH \\\n  --billing-mode PAY_PER_REQUEST',vs:'DynamoDB vs RDS: chọn DynamoDB khi mẫu truy cập biết trước, cần scale cực lớn; RDS khi query phức tạp, join, giao dịch đa bảng.',err:'Dùng Scan toàn bảng trong production, chọn partition key ít phân tán (vd: status), quên bật PITR.'},
    {c:'aws',n:'Amazon VPC',g:'Networking & Content Delivery',gl:'nodes',lvl:0,d:'Mạng ảo riêng của bạn trong AWS: tự định nghĩa CIDR, subnet, route table, gateway, firewall. Mọi tài nguyên AWS đều sống trong VPC.',u:['Tách public/private subnet cho kiến trúc 3-tier','Kết nối hybrid với on-prem qua VPN/Direct Connect','Cô lập workload theo môi trường/team'],lim:'VPC là tài nguyên regional; subnet tối thiểu /28, tối đa /16. Mỗi subnet mất 5 IP do AWS dự trữ.',pr:'VPC miễn phí; tốn tiền ở NAT Gateway, VPN, endpoint, data transfer.',cfg:'aws ec2 create-vpc --cidr-block 10.0.0.0/16\naws ec2 create-subnet --vpc-id vpc-0abc \\\n  --cidr-block 10.0.1.0/24 --availability-zone ap-northeast-1a\naws ec2 create-internet-gateway\naws ec2 attach-internet-gateway \\\n  --internet-gateway-id igw-0abc --vpc-id vpc-0abc',vs:'VPC (AWS) vs VPC (GCP): AWS regional theo AZ; GCP global, subnet theo region — xem Phần 5.',err:'Dùng dải CIDR chồng lấn với on-prem (không bao giờ peering/DX được), dồn mọi thứ vào public subnet, 1 NAT Gateway cho mọi AZ.'},
    {c:'aws',n:'AWS Transit Gateway',g:'Networking & Content Delivery',gl:'hub',lvl:2,d:'Hub trung tâm kết nối hàng nghìn VPC và mạng on-prem theo mô hình hub-and-spoke, thay cho mê cung VPC Peering.',u:['Doanh nghiệp nhiều VPC/account','Kết nối tập trung Direct Connect/VPN','Phân đoạn mạng bằng nhiều route table TGW'],lim:'Peering giữa các TGW khác region có giới hạn băng thông; cần thiết kế CIDR không chồng lấn toàn cục.',pr:'Theo giờ mỗi attachment + theo GB dữ liệu qua TGW.',cfg:'aws ec2 create-transit-gateway --description hub-tokyo\naws ec2 create-transit-gateway-vpc-attachment \\\n  --transit-gateway-id tgw-0abc --vpc-id vpc-0def \\\n  --subnet-ids subnet-0a1 subnet-0c1',vs:'TGW vs Peering: ≤ 3 VPC thì peering rẻ hơn; từ 4 VPC hoặc có on-prem chung thì TGW thắng.',err:'Quên route return ở phía VPC spoke, dùng 1 TGW route table cho mọi môi trường (prod lẫn dev).'},
    {c:'aws',n:'Amazon CloudFront',g:'Networking & Content Delivery',gl:'globe',lvl:0,d:'CDN toàn cầu: cache nội dung tại edge location gần người dùng, giảm latency và giảm tải origin (S3/ALB), tích hợp WAF và Lambda@Edge.',u:['Web/app toàn quốc & toàn cầu','Phân phối file tĩnh, video streaming','Chặn tấn công lớp 7 cùng AWS WAF'],lim:'Cache invalidation có giới hạn miễn phí; nội dung động cần cấu hình cache policy cẩn thận.',pr:'Theo request + GB truyền ra theo vùng địa lý; có gói tiết kiệm khi cam kết lưu lượng.',cfg:'aws cloudfront create-distribution \\\n  --origin-domain-name my-site.s3.ap-northeast-1.amazonaws.com \\\n  --default-root-object index.html',vs:'CloudFront vs Global Accelerator: CloudFront cache được nội dung HTTP; GA chỉ tăng tốc TCP/UDP không cache.',err:'Cache nhầm trang có cookie/đăng nhập cho mọi người dùng, quên gắn WAF, TTL quá dài khiến deploy mới không lên.'},
    {c:'aws',n:'Elastic Load Balancing (ALB)',g:'Networking & Content Delivery',gl:'scale',lvl:0,d:'ALB cân bằng tải lớp 7 (HTTP/HTTPS, WebSocket, gRPC): route theo path/host/header tới nhiều target group EC2, container, Lambda.',u:['Điểm vào duy nhất cho web/app multi-AZ','Chia microservices theo path /api, /web','Blue-green deployment theo trọng số target group'],lim:'ALB nằm ở public subnet (nếu internet-facing); cần tối thiểu 2 AZ. NLB dùng khi cần IP tĩnh/latency cực thấp lớp 4.',pr:'Theo giờ ALB + LCU (dung lượng xử lý). NLB/GWLB tính tương tự theo NLCU/GLCU.',cfg:'aws elbv2 create-load-balancer --name web-alb \\\n  --subnets subnet-pub-a subnet-pub-c --type application \\\n  --security-groups sg-alb',vs:'ALB vs NLB: ALB hiểu HTTP để route thông minh; NLB lớp 4 siêu nhanh, IP tĩnh, cho TCP/UDP/game/VoIP.',err:'Health check path sai khiến target bị loại oan, chỉ mở 1 AZ, quên bật access log.'},
    {c:'aws',n:'Amazon Route 53',g:'Networking & Content Delivery',gl:'route',lvl:1,d:'DNS managed độ sẵn sàng 100% SLA: public/private hosted zone, health check và nhiều chính sách định tuyến (weighted, latency, failover, geolocation).',u:['Quản lý domain & DNS cho mọi hệ thống','Failover active-passive giữa 2 region','Private zone phân giải nội bộ trong VPC'],lim:'DNS propagation phụ thuộc TTL phía client; private zone chỉ phân giải trong VPC đã liên kết.',pr:'Theo hosted zone/tháng + theo triệu query; health check tính riêng.',cfg:'aws route53 create-hosted-zone --name example.com \\\n  --caller-reference 2026-01\naws route53 change-resource-record-sets \\\n  --hosted-zone-id Z0123 --change-batch file://change.json',vs:'Route 53 vs Cloud DNS (GCP): tương đương; Route 53 mạnh ở routing policy + health check tích hợp failover.',err:'TTL quá cao trước ngày cutover migration, quên liên kết private zone với VPC mới.'},
    {c:'aws',n:'AWS IAM',g:'Security, Identity & Compliance',gl:'key',lvl:0,d:'Hệ thống danh tính & phân quyền của AWS: user, group, role, policy JSON. Mọi lệnh gọi API đều qua IAM đánh giá cho phép hay từ chối.',u:['Cấp quyền least-privilege cho người & workload','Role cho EC2/Lambda thay access key','Liên kết danh tính ngoài qua SAML/OIDC federation'],lim:'Policy có giới hạn kích thước/số lượng; đánh giá deny tường minh thắng mọi allow.',pr:'Miễn phí hoàn toàn.',cfg:'# Policy chỉ đọc 1 bucket S3\n{\n  "Version": "2012-10-17",\n  "Statement": [{\n    "Effect": "Allow",\n    "Action": ["s3:GetObject","s3:ListBucket"],\n    "Resource": ["arn:aws:s3:::my-bucket",\n                 "arn:aws:s3:::my-bucket/*"]\n  }]\n}',vs:'IAM user vs IAM Role: luôn ưu tiên Role (tạm thời, tự xoay vòng) cho workload; user + access key dài hạn là rủi ro số 1.',err:'Gắn AdministratorAccess cho mọi người, dùng tài khoản root hằng ngày, chia sẻ access key qua chat/email.'},
    {c:'aws',n:'Amazon SQS',g:'Application Integration',gl:'layers',lvl:0,d:'Hàng đợi message managed: tách rời (decouple) các thành phần, hấp thụ đỉnh tải, đảm bảo xử lý ít nhất một lần (standard) hoặc đúng thứ tự (FIFO).',u:['Đệm xử lý đơn hàng/email/báo cáo','Retry an toàn với DLQ khi xử lý lỗi','Fan-in cho pipeline ETL'],lim:'Message tối đa 256KB; FIFO giới hạn 3.000 msg/s (có batch). Lưu tối đa 14 ngày.',pr:'Theo triệu request; rất rẻ, gần như không đáng kể ở quy mô vừa.',cfg:'aws sqs create-queue --queue-name order-queue \\\n  --attributes VisibilityTimeout=60\naws sqs send-message --queue-url https://sqs.../order-queue \\\n  --message-body "{\\"orderId\\":\\"A1023\\"}"',vs:'SQS vs SNS: SQS là pull (consumer chủ động lấy, lưu đệm); SNS là push fan-out tới nhiều subscriber.',err:'Visibility timeout ngắn hơn thời gian xử lý khiến message bị xử lý trùng, không cấu hình DLQ.'},
    {c:'aws',n:'Amazon EventBridge',g:'Application Integration',gl:'zap',lvl:1,d:'Event bus serverless: nhận sự kiện từ AWS services, SaaS và ứng dụng của bạn, định tuyến theo rule tới Lambda, SQS, Step Functions…',u:['Kiến trúc event-driven giữa các microservices','Lịch chạy (scheduler) thay cron','Tích hợp SaaS (Zendesk, Datadog…) vào pipeline'],lim:'Rule khớp theo event pattern JSON — sai pattern là sự kiện “biến mất” lặng lẽ; có quota số rule/bus.',pr:'Theo triệu sự kiện đưa vào bus; sự kiện của AWS services miễn phí.',cfg:'aws events put-rule --name nightly-report \\\n  --schedule-expression "cron(0 15 * * ? *)"\naws events put-targets --rule nightly-report \\\n  --targets Id=1,Arn=arn:aws:lambda:...:function:report',vs:'EventBridge vs SNS: cần lịch + lọc nội dung sự kiện + schema thì EventBridge; fan-out đơn giản tốc độ cao thì SNS.',err:'Không lưu trữ (archive) sự kiện để replay khi consumer lỗi, đặt rule quá rộng khớp mọi sự kiện.'},
    {c:'aws',n:'AWS CloudFormation',g:'Management & Governance',gl:'doc',lvl:1,d:'IaC gốc của AWS: khai báo hạ tầng bằng template YAML/JSON, triển khai thành stack có quản lý vòng đời và rollback.',u:['Chuẩn hoá môi trường dev/stage/prod','Tài liệu hoá kiến trúc dạng code','Kết hợp CDK (sinh template) cho team dev'],lim:'Stack giới hạn số resource; drift khi có người sửa tay qua console.',pr:'Miễn phí (chỉ trả tiền tài nguyên tạo ra).',cfg:'Resources:\n  AppBucket:\n    Type: AWS::S3::Bucket\n    Properties:\n      VersioningConfiguration:\n        Status: Enabled\n# Triển khai:\n# aws cloudformation deploy --template-file infra.yaml \\\n#   --stack-name my-app --capabilities CAPABILITY_IAM',vs:'CloudFormation vs Terraform: CFN thuần AWS, tích hợp sâu; Terraform đa cloud — dự án multi-cloud AWS+GCP nên ưu tiên Terraform.',err:'Sửa tay resource do CFN quản lý gây drift, template không tách môi trường bằng parameter.'},
    {c:'aws',n:'Amazon CloudWatch',g:'Management & Governance',gl:'gauge',lvl:0,d:'Trung tâm observability: metrics, logs, alarms, dashboard, synthetics. Gần như mọi AWS service đều đẩy metric vào đây.',u:['Alarm CPU/RAM/latency → SNS/ASG','Tập trung log ứng dụng & hệ thống','Dashboard vận hành theo dự án'],lim:'Metric mặc định EC2 không có RAM/disk chi tiết — cần CloudWatch Agent. Log giữ mặc định “không hết hạn” dễ tốn tiền.',pr:'Theo metric tuỳ chỉnh, GB log ingest/lưu, số alarm & dashboard.',cfg:'aws cloudwatch put-metric-alarm --alarm-name high-cpu \\\n  --metric-name CPUUtilization --namespace AWS/EC2 \\\n  --statistic Average --period 300 --threshold 80 \\\n  --comparison-operator GreaterThanThreshold \\\n  --evaluation-periods 2 --alarm-actions arn:aws:sns:...:alerts',vs:'CloudWatch vs Managed Grafana: CloudWatch đủ cho vận hành AWS; Grafana khi cần dashboard đa nguồn (AWS + GCP + on-prem).',err:'Không đặt retention cho log group, alarm không gắn hành động, thiếu alarm về chi phí (Billing alarm).'},
    {c:'aws',n:'AWS Application Migration Service (MGN)',g:'Migration & Transfer',gl:'swap',lvl:1,d:'Service chủ lực cho rehost (lift & shift): cài agent lên server nguồn, replicate liên tục ở mức block, test và cutover lên EC2 trong vài phút downtime.',u:['Chuyển hàng loạt server VMware/vật lý/cloud khác về EC2','Thoát data center theo deadline','DR thí điểm sang AWS'],lim:'Hỗ trợ theo ma trận OS/kernel; cần cổng mạng 443 & 1500 tới AWS. Mỗi server miễn phí replicate 90 ngày.',pr:'Miễn phí trong 90 ngày/server; sau đó tính theo server đang replicate + chi phí EC2 khi chạy.',cfg:'# 1) Cài agent trên server nguồn (Linux):\nwget https://aws-application-migration-service-ap-northeast-1.s3.amazonaws.com/latest/linux/aws-replication-installer-init.py\nsudo python3 aws-replication-installer-init.py\n# 2) Chờ replicate → Launch test instance → Cutover từ MGN console',vs:'MGN vs AWS Transform: MGN tự rehost nguyên trạng; Transform phân tích & chuyển đổi sâu (VMware/.NET/mainframe) có AI hỗ trợ.',err:'Không chạy test launch trước cutover, quên kiểm tra license phần mềm gắn MAC/IP, cutover giờ cao điểm.'},
    {c:'aws',n:'AWS Database Migration Service (DMS)',g:'Migration & Transfer',gl:'refresh',lvl:1,d:'Chuyển database với downtime gần 0: full load + CDC (change data capture) liên tục từ Oracle, SQL Server, MySQL… sang RDS/Aurora/DynamoDB/Redshift.',u:['Chuyển Oracle → Aurora PostgreSQL (cùng SCT đổi schema)','Đồng bộ DB sang AWS phục vụ phân tích','Gộp nhiều DB nguồn về một đích'],lim:'Một số kiểu dữ liệu/đối tượng (trigger, procedure) cần SCT hoặc xử lý tay; LOB lớn làm chậm CDC.',pr:'Theo giờ replication instance + lưu trữ log; có lớp miễn phí 6 tháng cho instance dms.t3.micro khi chuyển về RDS/Aurora.',cfg:'aws dms create-replication-task \\\n  --replication-task-identifier ora-to-aurora \\\n  --source-endpoint-arn arn:aws:dms:...:endpoint:SRC \\\n  --target-endpoint-arn arn:aws:dms:...:endpoint:TGT \\\n  --migration-type full-load-and-cdc \\\n  --table-mappings file://mappings.json',vs:'DMS vs Database Migration Service (GCP): cùng mô hình full load + CDC; DMS đa dạng engine đích hơn, GCP DMS mạnh ở PostgreSQL/MySQL → Cloud SQL/AlloyDB.',err:'Không kiểm chứng dữ liệu sau chuyển (validation), bỏ qua sequence/index, đánh giá thấp độ trễ CDC giờ cao điểm.'},
    {c:'aws',n:'Amazon Athena',g:'Analytics',gl:'search',lvl:1,d:'Truy vấn SQL trực tiếp trên file trong S3 (CSV, JSON, Parquet…) — serverless, không cần nạp dữ liệu vào database.',u:['Phân tích log (CloudTrail, ALB, CloudFront) trên S3','Data lake query không cần dựng cluster','Báo cáo ad-hoc cho team data'],lim:'Hiệu năng phụ thuộc định dạng file: Parquet + partition nhanh & rẻ hơn CSV thô hàng chục lần.',pr:'Theo TB dữ liệu quét — tối ưu partition/format là tối ưu chi phí.',cfg:'-- DDL khai báo bảng trên S3\nCREATE EXTERNAL TABLE alb_logs (\n  time string, elb string, client_ip string,\n  request string, status int)\nPARTITIONED BY (day string)\nSTORED AS PARQUET\nLOCATION \'s3://my-lake/alb-logs/\';',vs:'Athena vs Redshift: Athena cho truy vấn ad-hoc trên S3 không quản trị; Redshift cho data warehouse tải đều, query phức tạp lặp lại.',err:'Quét toàn bộ bucket không partition, để dữ liệu dạng CSV/JSON thô thay vì Parquet.'},
    {c:'aws',n:'Amazon Bedrock',g:'Machine Learning',gl:'spark',lvl:1,d:'Nền tảng GenAI managed: truy cập nhiều họ foundation model (Amazon Nova, Claude, Llama, Mistral…) qua một API, kèm Knowledge Bases (RAG), Agents và Guardrails.',u:['Chatbot RAG trên tài liệu nội bộ','Tóm tắt, phân loại, trích xuất văn bản','Xây AI agent gọi API nội bộ (Bedrock AgentCore)'],lim:'Quota token/phút theo model & region; model mới cần xin cấp quyền truy cập trong console.',pr:'Theo token đầu vào/ra (on-demand) hoặc provisioned throughput cho tải ổn định lớn.',cfg:'# Gọi model bằng AWS CLI\naws bedrock-runtime converse \\\n  --model-id amazon.nova-lite-v1:0 \\\n  --messages \'[{"role":"user","content":[{"text":"Tóm tắt văn bản sau…"}]}]\'',vs:'Bedrock vs SageMaker: Bedrock khi dùng model có sẵn qua API; SageMaker khi cần train/fine-tune & host model tự quản sâu.',err:'Không đặt Guardrails lọc nội dung, gửi dữ liệu nhạy cảm mà chưa rõ chính sách dùng dữ liệu của model, quên giới hạn ngân sách token.'},
    {c:'aws',n:'Amazon SageMaker',g:'Machine Learning',gl:'bot',lvl:2,d:'Nền tảng ML toàn trình: chuẩn bị dữ liệu, train, tune, deploy model với hạ tầng quản lý (kể cả GPU/Trainium), MLOps pipeline. SageMaker Unified Studio (2025) hợp nhất trải nghiệm data + AI.',u:['Train model riêng trên dữ liệu doanh nghiệp','Deploy endpoint realtime/batch cho model tự build','Pipeline MLOps chuẩn hoá'],lim:'Đường cong học tập dốc; chi phí GPU chạy train/endpoint cần quản trị chặt (tắt khi không dùng).',pr:'Theo giờ instance train/endpoint + lưu trữ; có Savings Plans cho SageMaker.',cfg:'# Deploy model lên endpoint (Python SDK)\nfrom sagemaker.sklearn import SKLearnModel\nmodel = SKLearnModel(model_data="s3://bucket/model.tar.gz",\n                     role=role, entry_point="inference.py")\npredictor = model.deploy(instance_type="ml.m5.large",\n                         initial_instance_count=1)',vs:'SageMaker vs Vertex AI (GCP): tương đương vai trò; Vertex AI gắn chặt Gemini & BigQuery, SageMaker gắn hệ sinh thái AWS & Bedrock.',err:'Để endpoint GPU chạy 24/7 cho mô hình ít dùng, không versioning dữ liệu train.'},

    {c:'gcp',n:'Compute Engine',g:'Compute',gl:'server',lvl:0,d:'Máy ảo IaaS của Google Cloud: chọn máy theo dòng N2/C3/C4, Tau… hoặc custom CPU/RAM, gắn Persistent Disk/Hyperdisk, chạy trong zone.',u:['Web/app server cần kiểm soát OS','Workload Windows/Linux truyền thống','HPC/GPU với máy chuyên dụng'],lim:'VM nằm trong 1 zone — chống lỗi zone bằng Managed Instance Group đa zone/regional.',pr:'Theo giây (tối thiểu 1 phút với một số loại), giảm tự động Sustained Use Discounts, Spot VMs rẻ tới ~60–91%.',cfg:'gcloud compute instances create web-1 \\\n  --zone=asia-northeast1-a --machine-type=e2-medium \\\n  --image-family=debian-12 --image-project=debian-cloud \\\n  --tags=http-server',vs:'Compute Engine vs EC2: tương đương trực tiếp; khác ở VPC global của GCP và giảm giá tự động SUD phía GCP.',err:'Tạo VM đơn lẻ không MIG cho production, mở firewall 0.0.0.0/0 vào SSH, quên đặt lịch tắt VM dev.'},
    {c:'gcp',n:'Cloud Run',g:'Containers',gl:'box',lvl:0,d:'Chạy container serverless: đưa image, Google lo scale từ 0 đến rất lớn theo request, trả tiền theo thời gian xử lý thực tế. Cũng host được function (Cloud Run functions) và job.',u:['API/web service dạng container','Microservice scale theo traffic','Job batch ngắn theo lịch/sự kiện'],lim:'Request timeout tối đa 60 phút; kết nối VPC qua Direct VPC egress/connector; cold start khi scale từ 0 (giảm bằng min instances).',pr:'Theo vCPU-giây + GB-giây + số request; scale về 0 = gần như 0 đồng khi không có traffic.',cfg:'gcloud run deploy api-service \\\n  --image=asia-northeast1-docker.pkg.dev/PROJECT/repo/api:v1 \\\n  --region=asia-northeast1 --allow-unauthenticated \\\n  --min-instances=0 --max-instances=20',vs:'Cloud Run vs Lambda: Cloud Run chạy mọi container/ngôn ngữ, request dài tới 60 phút; Lambda gọn cho hàm sự kiện ngắn trong hệ AWS.',err:'Đặt min instances cao vô ích tốn tiền, không giới hạn max instances khiến chi phí bùng khi bị gọi lặp.'},
    {c:'gcp',n:'Google Kubernetes Engine (GKE)',g:'Containers',gl:'hub',lvl:1,d:'Kubernetes managed của Google — “quê hương” của Kubernetes. Hai chế độ: Standard (tự quản node) và Autopilot (Google quản node, trả theo pod).',u:['Nền tảng microservices chuẩn doanh nghiệp','Workload cần ecosystem Kubernetes (Helm, Istio…)','Chạy đa region với GKE multi-cluster'],lim:'Autopilot có ràng buộc bảo mật/pod spec; nâng cấp version cần theo lộ trình release channel.',pr:'Phí quản lý cluster + tài nguyên node/pod; Autopilot tính theo tài nguyên pod yêu cầu.',cfg:'gcloud container clusters create-auto prod-cluster \\\n  --region=asia-northeast1\ngcloud container clusters get-credentials prod-cluster \\\n  --region=asia-northeast1\nkubectl apply -f deployment.yaml',vs:'GKE vs EKS: GKE thường được đánh giá vận hành nhẹ & nâng cấp mượt hơn; EKS thắng khi workload gắn chặt dịch vụ AWS.',err:'Chạy cluster 1 zone cho production, không bật Workload Identity (dùng key JSON trong pod).'},
    {c:'gcp',n:'Cloud Storage',g:'Storage',gl:'bucket',lvl:0,d:'Object storage của GCP: bucket toàn cầu theo tên duy nhất, các lớp Standard/Nearline/Coldline/Archive, Object Lifecycle tự hạ lớp theo tuổi dữ liệu.',u:['Data lake, backup, archive','Lưu media, tài sản web qua CDN','Nguồn/đích cho BigQuery, Dataflow'],lim:'Tên bucket duy nhất toàn cầu; không phải filesystem — dùng Filestore khi cần NFS.',pr:'Theo GB-tháng theo lớp + phí operation (Class A/B) + phí truy xuất sớm ở lớp lạnh.',cfg:'gcloud storage buckets create gs://my-data-lake \\\n  --location=asia-northeast1 --uniform-bucket-level-access\ngcloud storage rsync -r ./data gs://my-data-lake/raw/',vs:'Cloud Storage vs S3: tương đương; S3 có hệ sinh thái storage class & tính năng (Tables/Vectors) rộng hơn, GCS đơn giản hơn về mô hình lớp.',err:'Bật quyền public allUsers cho bucket dữ liệu, không đặt lifecycle khiến dữ liệu nóng nằm mãi ở Standard.'},
    {c:'gcp',n:'Cloud SQL',g:'Databases',gl:'db',lvl:0,d:'Database quan hệ managed (MySQL, PostgreSQL, SQL Server): backup tự động, HA regional, replica đọc, bảo trì do Google quản.',u:['DB cho ứng dụng web truyền thống','Đích chuyển đổi từ RDS/on-prem bằng DMS','Môi trường dev/stage nhanh gọn'],lim:'HA là theo region (standby cùng region); cần scale lớn/phân tán toàn cầu thì cân nhắc AlloyDB/Spanner.',pr:'Theo vCPU/RAM + storage + backup; có committed use discounts.',cfg:'gcloud sql instances create prod-db \\\n  --database-version=POSTGRES_15 --tier=db-custom-2-7680 \\\n  --region=asia-northeast1 --availability-type=REGIONAL \\\n  --backup',vs:'Cloud SQL vs AlloyDB: AlloyDB (tương thích PostgreSQL) nhanh & scale tốt hơn cho tải lớn; Cloud SQL đa engine & đơn giản hơn.',err:'Để instance public IP mở cho mọi dải, không bật backup/PITR, dùng tier quá nhỏ cho production.'},
    {c:'gcp',n:'AlloyDB for PostgreSQL',g:'Databases',gl:'db',lvl:1,d:'Database tương thích PostgreSQL do Google thiết kế lại cho cloud: tách compute/storage, nhanh hơn PostgreSQL chuẩn cho giao dịch, có columnar engine cho phân tích HTAP. Có bản Omni chạy ngoài GCP.',u:['Thay thế PostgreSQL/Oracle tải lớn','Ứng dụng cần cả OLTP + phân tích tại chỗ','Đích migration từ Aurora/RDS PostgreSQL'],lim:'Chỉ tương thích PostgreSQL (không phải MySQL); tính năng mở rộng theo phiên bản PG hỗ trợ.',pr:'Theo vCPU/RAM cluster + storage + backup; có Database Savings Plans phía AWS là đối trọng — GCP dùng CUD.',cfg:'gcloud alloydb clusters create prod-cluster \\\n  --region=asia-northeast1 --network=default\ngcloud alloydb instances create prod-primary \\\n  --cluster=prod-cluster --region=asia-northeast1 \\\n  --instance-type=PRIMARY --cpu-count=4',vs:'AlloyDB vs Aurora: hai đối thủ trực tiếp — Aurora thắng trong hệ AWS & scale read; AlloyDB mạnh ở HTAP và hiệu năng PostgreSQL thuần.',err:'Chuyển từ MySQL sang AlloyDB mà quên khác biệt engine, không kiểm thử extension PostgreSQL đang dùng.'},
    {c:'gcp',n:'BigQuery',g:'Analytics',gl:'chart',lvl:0,d:'Data warehouse serverless của Google: tách hẳn storage/compute, quét hàng TB/PB trong vài giây bằng SQL, có BigQuery ML và tích hợp Gemini. Lá bài mạnh nhất của GCP cho analytics.',u:['Kho dữ liệu phân tích doanh nghiệp','Phân tích log/sự kiện quy mô lớn','BI với Looker Studio/Looker'],lim:'Chi phí theo dữ liệu quét (on-demand) — query thiếu partition/clustering rất tốn; hoặc mua slot theo dung lượng.',pr:'On-demand theo TB quét hoặc capacity (slot) theo giờ/tháng; storage tính riêng, rẻ.',cfg:'-- Tạo dataset & truy vấn phân tích\nbq mk --dataset --location=asia-northeast1 PROJECT:analytics\nSELECT day, COUNT(*) AS orders\nFROM `PROJECT.analytics.orders`\nWHERE day >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)\nGROUP BY day ORDER BY day;',vs:'BigQuery vs Redshift: BigQuery serverless thật sự, không quản cluster; Redshift hợp khi workload warehouse ổn định trong hệ AWS và cần kiểm soát dung lượng.',err:'SELECT * trên bảng không partition, join không điều kiện, để bảng tạm không hết hạn.'},
    {c:'gcp',n:'Pub/Sub',g:'Analytics',gl:'waves',lvl:0,d:'Messaging service toàn cầu: publisher đẩy message vào topic, subscriber nhận qua push/pull với đảm bảo at-least-once, scale không giới hạn thực tế. Tương đương SQS+SNS gộp của AWS.',u:['Event streaming cho Dataflow/BigQuery','Tách rời microservices bằng sự kiện','Thu thập sự kiện IoT/app toàn cầu'],lim:'Message tối đa 10MB; thứ tự chỉ đảm bảo khi bật ordering key theo từng key.',pr:'Theo GB dữ liệu truyền + lưu trữ message chưa ack.',cfg:'gcloud pubsub topics create order-events\ngcloud pubsub subscriptions create order-sub \\\n  --topic=order-events --ack-deadline=60\ngcloud pubsub topics publish order-events \\\n  --message="{\\"orderId\\":\\"A1023\\"}"',vs:'Pub/Sub vs Kinesis: Pub/Sub là messaging theo message; Kinesis là stream có shard & lưu phát lại theo thời gian — chọn theo mô hình tiêu thụ.',err:'Không cấu hình dead-letter topic, ack quá sớm trước khi xử lý xong khiến mất message khi crash.'},
    {c:'gcp',n:'Vertex AI',g:'AI & Machine Learning',gl:'spark',lvl:1,d:'Nền tảng AI/ML hợp nhất của Google (đang mở rộng thành Gemini Enterprise Agent Platform): Model Garden 200+ mô hình, Gemini, train/deploy model riêng, Agent Engine chạy AI agent, Vertex AI Search cho RAG doanh nghiệp.',u:['Ứng dụng GenAI dùng Gemini qua API/SDK','Train & deploy model ML riêng (kể cả trên TPU)','Xây agent doanh nghiệp + tìm kiếm tài liệu nội bộ'],lim:'Quota theo region/model cho Gemini; dữ liệu train/inference cần quản trị theo region vì yêu cầu cư trú dữ liệu.',pr:'Theo token (Gemini) hoặc theo giờ node train/endpoint; Agent/Search tính theo usage riêng.',cfg:'# Gọi Gemini qua gcloud / API\ngcloud ai models list --region=asia-northeast1\ncurl -X POST \\\n  "https://asia-northeast1-aiplatform.googleapis.com/v1/projects/PROJECT/locations/asia-northeast1/publishers/google/models/gemini-2.5-flash:generateContent" \\\n  -H "Authorization: Bearer $(gcloud auth print-access-token)" \\\n  -d \'{"contents":[{"role":"user","parts":[{"text":"Xin chào"}]}]}\'',vs:'Vertex AI vs Bedrock: Vertex AI gắn chặt Gemini + BigQuery + TPU; Bedrock đa nhà cung cấp mô hình hơn trong một API.',err:'Không giới hạn quota/ngân sách cho API key GenAI, bỏ qua đánh giá (evaluation) trước khi đưa agent vào production.'},
    {c:'gcp',n:'Cloud VPC (Google Cloud)',g:'Networking',gl:'nodes',lvl:0,d:'Mạng ảo của GCP nhưng ở phạm vi TOÀN CẦU: một VPC chứa nhiều subnet ở nhiều region, route mặc định phủ khắp VPC. Đây là khác biệt kiến trúc lớn nhất so với AWS.',u:['Một mạng thống nhất cho ứng dụng đa region','Shared VPC chia mạng cho nhiều project/team','Kết nối hybrid bằng Cloud Router + Interconnect'],lim:'Firewall rule là tầng network (áp theo tag/service account); subnet không chồng CIDR trong cùng VPC.',pr:'VPC miễn phí; tính phí ở Cloud NAT, VPN, Interconnect, traffic egress.',cfg:'gcloud compute networks create prod-net --subnet-mode=custom\ngcloud compute networks subnets create tokyo-app \\\n  --network=prod-net --region=asia-northeast1 \\\n  --range=10.10.0.0/20\ngcloud compute firewall-rules create allow-web \\\n  --network=prod-net --allow=tcp:80,tcp:443 \\\n  --source-ranges=0.0.0.0/0 --target-tags=http-server',vs:'VPC GCP vs VPC AWS: GCP global + subnet regional; AWS regional + subnet theo AZ. Route & firewall của GCP tự lan khắp VPC.',err:'Dùng auto-mode VPC cho production (CIDR cố định dễ chồng lấn), quên rằng firewall mặc định có implied deny cần rule rõ ràng.'},
    {c:'gcp',n:'Cloud Load Balancing',g:'Networking',gl:'scale',lvl:0,d:'Hệ load balancer phần mềm của Google: đặc biệt Global External Application LB dùng 1 địa chỉ anycast IP duy nhất cho toàn cầu, định tuyến tới region gần nhất.',u:['Web toàn cầu với 1 IP duy nhất','Cân bằng tải đa region tự failover','Internal LB cho microservices trong VPC'],lim:'Mỗi loại LB (global/regional, external/internal, L4/L7) có phạm vi khác nhau — chọn sai loại là lỗi thiết kế phổ biến.',pr:'Theo forwarding rule + GB dữ liệu xử lý; global LB tính theo quy mô toàn cầu.',cfg:'gcloud compute backend-services create web-backend \\\n  --global --load-balancing-scheme=EXTERNAL_MANAGED\ngcloud compute url-maps create web-map \\\n  --default-service=web-backend',vs:'Cloud LB vs ALB: ALB regional theo AZ; Global LB của GCP anycast toàn cầu thực thụ — lợi thế lớn cho ứng dụng đa châu lục.',err:'Chọn regional LB cho bài toán toàn cầu, quên cấu hình health check & CDN trên cùng backend.'},
    {c:'gcp',n:'Google Cloud IAM',g:'Security & Identity',gl:'key',lvl:0,d:'Phân quyền theo tài nguyên phân cấp Organization → Folder → Project → Resource: gán role (basic/predefined/custom) cho member (user, group, service account).',u:['Quản trị tập trung nhiều project bằng folder & org policy','Service account cho workload thay key tĩnh','Áp chính sách tổ chức (Organization Policy) chặn cấu hình sai'],lim:'Quyền thừa hưởng từ cấp trên xuống — gán rộng ở Organization là rủi ro lớn; key JSON của service account cần tránh tối đa (dùng Workload Identity).',pr:'Miễn phí.',cfg:'gcloud projects add-iam-policy-binding PROJECT \\\n  --member="user:dev@example.com" \\\n  --role="roles/run.developer"\n# Ưu tiên Workload Identity thay vì tải key JSON',vs:'IAM GCP vs IAM AWS: GCP theo cây tài nguyên & role predefined rất mạnh; AWS policy JSON linh hoạt chi tiết theo action/resource hơn.',err:'Gán roles/owner cho tài khoản cá nhân, tải key service account về máy dev, không dùng thư mục (folder) phân môi trường.'}
    ];

